{
  "labels": [
    {
      "i": 30,
      "speaker": "bot",
      "text": "ठीक है?"
    },
    {
      "i": 31,
      "speaker": "bot",
      "text": "10 feet note कर लिया।"
    },
    {
      "i": 32,
      "speaker": "bot",
      "text": "एक minute आपकी city और state भी बता दीजिए please।"
    },
    {
      "i": 33,
      "speaker": "caller",
      "text": "हमर घर आ रहा।"
    },
    {
      "i": 34,
      "speaker": "bot",
      "text": "कोई बात नहीं आप अपनी city और state का नाम बता दीजिए ताकि seller आपको सही जानकारी दे सके।"
    },
    {
      "i": 35,
      "speaker": "caller",
      "text": "अरे CC तो नहीं है जा रहा जिला घर आ रहा आ रहा।"
    },
    {
      "i": 36,
      "speaker": "bot",
      "text": "माफ़ कीजिए आपकी city का नाम मुझे समझ नहीं आया।"
    },
    {
      "i": 37,
      "speaker": "bot",
      "text": "कृपया एक बार साफ़-साफ़ अपने city और state का नाम बता दीजिए।"
    },
    {
      "i": 38,
      "speaker": "caller",
      "text": "राखा।"
    },
    {
      "i": 39,
      "speaker": "bot",
      "text": "कोई बात नहीं।"
    }
  ]
}
